#!/usr/bin/env python3
"""Partners hub, four partner pages, Perks, Concerto+, Investors, Press.

Every partner page shows the partnership the way a fan would meet it in the
app: an in-app preview rendered from the app's own design system (the Home
Perk card in src/components/HomeCards.tsx and the Your Night rows), the
three-front value standard, placements, and the Netlify interest form kept in
scripts/forms/<type>.html.
"""
import html, sys
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / 'scripts'))
from public_chrome import header_html, page_end, HEAD_ASSETS, product_screen, photo_slot, APP, SITE

def e(x): return html.escape(str(x or ''), quote=True)

def head(title, desc, canonical, extra=''):
    return (f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
            f'<meta name="apple-itunes-app" content="app-id=6744903414"><title>{e(title)}</title><meta name="description" content="{e(desc)}">'
            f'<meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="{SITE+canonical}">'
            f'<meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website">'
            f'<meta property="og:url" content="{SITE+canonical}"><meta property="og:image" content="{SITE}/ConcertoSocialPreview.png"><meta property="og:site_name" content="Concerto">'
            f'<meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="{SITE}/ConcertoSocialPreview.png">'
            f'<link rel="icon" href="/favicon.ico" sizes="any"><link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="apple-touch-icon" href="/apple-touch-icon.png">'
            f'{HEAD_ASSETS}{extra}</head><body class="public-site">') + header_html(canonical)

def phone(name, alt):
    return f'<div class="device"><div class="iphone-screen"><img src="{product_screen(name)}" width="941" height="2048" alt="{e(alt)}" loading="lazy"></div></div>'

# ---------------------------------------------------------------- in-app preview
def app_preview(show, venue, partner, offer, sub, place='home'):
    """Home-style Perk card exactly as HomeCards.tsx renders it, inside a phone."""
    return f'''<div class="device app-preview" aria-label="How this partnership appears in Concerto"><div class="iphone-screen ap-screen">
<div class="ap-status"><span>12:00</span><span class="ap-status-icons"><i class="ap-signal"></i><i class="ap-wifi"></i><i class="ap-battery"></i></span></div>
<div class="ap-greeting">GOOD EVENING</div><div class="ap-lockup"><img src="/img/lockup.png" alt=""></div>
<div class="ap-next"><div class="ap-kicker">YOUR NEXT SHOW</div><div class="ap-show">{e(show)}</div><div class="ap-venue">{e(venue)} · Doors 7:30 PM</div><div class="ap-count"><span><b>12</b>DAYS</span><span class="ap-colon">:</span><span><b>04</b>HRS</span><span class="ap-colon">:</span><span><b>21</b>MIN</span></div></div>
<div class="ap-perk"><div class="ap-perk-top"><span class="ap-gift"></span><span class="ap-perk-kicker">CONCERTO PERK NEAR YOUR SHOW</span><span class="ap-partner">PARTNER</span></div><div class="ap-perk-name">{e(partner)}</div><div class="ap-perk-offer">{e(offer)}</div><div class="ap-perk-sub">{e(sub)}</div><div class="ap-perk-link">View Perk <span>→</span></div></div>
<div class="ap-rail-head"><span>Nearby Restaurants</span><span class="ap-rail-link">View venue</span></div><div class="ap-chips"><span>{e(venue)}</span><span>Filter</span></div><div class="ap-nearby"><div class="ap-near ap-near-photo"><b>{e(partner)}</b><span>Cafe · 6 min</span></div><div class="ap-near ap-near-mono"><i>7</i><b>7th Street Tavern</b><span>Bar · 4 min</span></div></div>
<div class="ap-tabs"><span class="on">Home</span><span>Venues</span><span>Tours</span><span>Near Me</span><span>Account</span></div>
</div></div>'''

def preview_block(kind, show, venue, partner, offer, sub, placements):
    tiles = ''.join(f'<div class="placement"><span>{e(k)}</span><h3>{e(t)}</h3><p>{e(p)}</p></div>' for k, t, p in placements)
    return f'''<section class="section dark preview-section"><div class="shell preview-layout"><div class="preview-copy"><p class="eyebrow">How it appears in Concerto</p><h2>Fans meet the offer where the decision happens.</h2><p class="lead">This is the Home card a fan sees when a Concerto Partner has a real benefit near their saved show. The same offer carries into Your Night, the venue page, and Concerto Perks. Paid placements are always labeled Partner.</p><div class="placement-grid two">{tiles}</div><p class="preview-note">Rendered from the app's design system with example content. Your live placement uses your name, your offer, and your action.</p></div><div class="preview-phone">{app_preview(show, venue, partner, offer, sub)}</div></div></section>'''

