def three_front(p):
    def col(title, kicker, items):
        lis = ''.join(f'<li>{e(x)}</li>' for x in items)
        return f'<article class="card"><p class="kicker">{kicker}</p><h3>{title}</h3><ul class="clean-list">{lis}</ul></article>'
    return f'''<section class="section"><div class="shell"><p class="eyebrow">The three-front standard</p><h2>Every partnership has to work for the fan, for you, and for Concerto.</h2><div class="grid3">{col('A reason to care.','What fans get',p['fans'])}{col('A useful commercial outcome.','What you get',p['you'])}{col('A real contribution.','What Concerto looks for',p['concerto'])}</div></div></section>'''

def examples(p):
    cards = ''.join(f'<article class="card"><h3>{e(t)}</h3><p>{e(d)}</p></article>' for t, d in p['examples'])
    return f'<section class="section"><div class="shell"><p class="eyebrow">Ways to start</p><h2>Three partnerships we can launch this season.</h2><div class="grid3">{cards}</div></div></section>'

def partner_page(slug, p):
    form = (ROOT / 'scripts/forms' / f'{slug}.html').read_text()
    canonical = f'/partners/{slug}'
    other = ''.join(f'<a class="coming-card" href="/partners/{k}"><strong>{e(v["label"])}</strong><span>{e(v["title"])}</span></a>' for k, v in PARTNERS.items() if k != slug)
    return head(f'{p["label"]} | Concerto Partners', p['desc'], canonical) + f'''<main>
<section class="hero-public"><div class="site-shell wide hero-grid"><div class="hero-copy"><p class="eyebrow">{e(p['label'])}</p><h1>{e(p['title'])}</h1><p class="lead">{e(p['desc'])}</p><div class="hero-actions"><a class="btn-primary" href="#interest">Express interest</a><a class="btn-secondary" href="/partners">All partner types</a></div></div><div class="device-stage single">{app_preview(p['show'], p['venue'], p['partner'], p['offer'], p['sub'])}</div></div></section>
{three_front(p)}
{preview_block(slug, p['show'], p['venue'], p['partner'], p['offer'], p['sub'], p['placements'])}
{examples(p)}
<section class="section" id="interest"><div class="shell form-shell"><div><p class="eyebrow">Express interest</p><h2>Tell us what you would bring.</h2><p class="lead">Partnerships go to partnerships@concertocity.com. We reply to every serious inquiry with a placement plan and what it would take to launch.</p><p class="lead" style="margin-top:14px">Concerto Picks stay editorial and are never for sale. Partner placements are always labeled.</p></div>{form}</div></section>
<section class="setlist-section alt"><div class="site-shell"><div class="catalog-intro"><h2>Other partner types.</h2></div><div class="coming-grid related-grid" style="grid-template-columns:repeat(3,minmax(0,1fr))">{other}</div></div></section>
</main>''' + page_end()

for slug, p in PARTNERS.items():
    (ROOT / f'partner-{slug}.html').write_text(partner_page(slug, p))

